contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount, address target) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);

        c.withdraw(amount); if (__ESBMC_reverted()) return;

        c.withdrawAll(); if (__ESBMC_reverted()) return;

        c.sendMoney(target, amount); if (__ESBMC_reverted()) return;

        assert(true);
    }

    receive() external payable {}
}

